const SQUISH_VECTOR_ASSETS = await (async () => {
  const errorNode=document.getElementById('error');
  try {
    const response=await fetch(new URL('assets/svg/manifest.json',document.baseURI));
    if(!response.ok)throw new Error('Authored SVG manifest failed to load: '+response.status);
    const manifest=await response.json();
    if(manifest.schemaVersion!==1||manifest.compileMode!=='browser-startup'||!Array.isArray(manifest.assets)||manifest.assets.length!==19)throw new Error('Authored SVG manifest has an unexpected inventory');
    const loader=createVectorAssetLoader({maxEntries:32});
    const entries=await Promise.all(manifest.assets.map(async item=>{
      const asset=await loader.load(new URL(item.path,document.baseURI).href,{sourcePath:item.path,expectedSha256:item.sha256,maxBytes:512*1024,curveSegments:16,includeSourcePaths:true});
      if(asset.metadata.id!==item.id)throw new Error('Authored SVG id mismatch: '+item.path);
      const authored=asset.metadata.styles?.filter(style=>style.kind==='yarn'||style.kind==='sketch')||[];
      const shaderSurfaces=asset.geometry.shaderSurfaces??[];
      if(authored.some(style=>style.backend!=='shader'))throw new Error('Authored shader style is missing: '+item.path);
      if(shaderSurfaces.length!==authored.length)throw new Error('GameKit shader surface count mismatch: '+item.path);
      if(authored.length&&asset.geometry.drawOrder?.filter(command=>command.kind==='surface').length!==authored.length)throw new Error('GameKit draw order is incomplete: '+item.path);
      return [item.key,asset];
    }));
    const loaded=Object.fromEntries(entries);
    if(Object.keys(loaded).length!==19)throw new Error('Authored SVG keys must be unique');
    return Object.freeze(loaded);
  } catch(error) {
    if(errorNode)errorNode.textContent='SVG 불러오기 실패: '+String(error?.message||error);
    throw error;
  }
})();
