 rebuild(entities){this.buckets.clear();this.entities.clear();this.maxRadius=0;const bounds=this.bounds={x0:Infinity,x1:-Infinity,y0:Infinity,y1:-Infinity};for(const e of entities){if(e.health.current<=0)continue;this.entities.set(e.id,e);this.maxRadius=Math.max(this.maxRadius,e.radius);const x=Math.floor(e.position.x/this.size),y=Math.floor(e.position.y/this.size);bounds.x0=Math.min(bounds.x0,x);bounds.x1=Math.max(bounds.x1,x);bounds.y0=Math.min(bounds.y0,y);bounds.y1=Math.max(bounds.y1,y);const key=this.key(x,y);let b=this.buckets.get(key);if(!b)this.buckets.set(key,b=[]);b.push(e)}}
