 update(unit,dt){for(const key of Object.keys(this.exposure)){this.exposure[key]=Math.max(0,this.exposure[key]-dt);if(!this.exposure[key])delete this.exposure[key]}this.frozen=Math.max(0,this.frozen-dt);this.slow.left=Math.max(0,this.slow.left-dt);if(this.burn.left>0){const elapsed=Math.min(dt,this.burn.left);this.burn.left-=elapsed;unit.applyDamage({damage:this.burn.dps*elapsed})}}
