 add(e){if(e.space==='hatch'&&e.type==='text')this.effects=this.effects.filter(f=>!(f.space==='hatch'&&f.type==='text'&&Math.abs(f.x-e.x)<78));if(e.space==='field'&&e.type==='text'){this.effects=this.effects.filter(f=>!(f.space===e.space&&f.type==='text'&&Math.abs(f.x-e.x)<45&&Math.abs(f.y-e.y)<30))}if(e.type==='thread'&&this.effects.filter(f=>f.type==='thread').length>=Config.capacity.particles)return;this.effects.push(e)}
 update(dt,active){if(!active)return;this.time+=dt;for(const e of this.effects){e.age+=dt;if(e.vx)e.x+=e.vx*dt;if(e.vy)e.y+=e.vy*dt;if(e.type==='piece'){e.vy+=530*dt;e.rot+=e.spin*dt}else if(e.type==='thread'){e.vy+=30*dt;e.vx*=Math.exp(-dt*2)}}this.effects=this.effects.filter(e=>e.age<e.life)}
