    roundedRect(ctx,x-27,y-25+off,54,45,7,i%2?tint(egg.material.shell,-.13):egg.material.shell);
    ctx.strokeStyle=tint(egg.material.color,-.36);ctx.lineWidth=here?2.8:1.3;ctx.beginPath();ctx.roundRect(x-27,y-25+off,54,45,7);ctx.stroke();
