   cup.quadraticCurveTo(0,94,53,76);cup.bezierCurveTo(64,57,77,-16,73,-68);
   cup.quadraticCurveTo(0,-88,-73,-68);cup.closePath();
   ctx.fillStyle='rgba(240,251,252,.29)';ctx.fill(cup);
