  ctx.save();ctx.clip(bodyPath);const wash=ctx.createRadialGradient(-30,-38,5,0,4,100);wash.addColorStop(0,'#fff8ff66');wash.addColorStop(.6,'#ffffff00');wash.addColorStop(1,'#775f8540');ctx.fillStyle=wash;ctx.fillRect(-100,-110,200,220);
