   if(done){ctx.fillStyle='#8e7b9d20';ctx.beginPath();ctx.ellipse(0,2,sx*.78,syy*.42,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f2e7ef45';ctx.lineWidth=1;ctx.beginPath();ctx.arc(-2,-1,sx*.38,3.4,5.5);ctx.stroke();ctx.restore();continue}
   ctx.fillStyle='#75657e2c';ctx.beginPath();ctx.ellipse(2,4,sx*1.05,syy*.72,0,0,Math.PI*2);ctx.fill();
