   g.addColorStop(0,pressed?'#efe5ef':ready?'#fff8ef':active?'#fdf0f4':'#eee2f0');g.addColorStop(.47,ready?'#dfbfe2':active?'#e4ccdf':'#d3c3de');g.addColorStop(1,tint(active?'#a987ad':'#a28aaa',b.tone));
