 showGrowth(group,node,pane){this.growthSelection=node||this.growthSelections[group]||Config.upgrades.find(d=>d.group===group).id;this.growthPane=pane||(node?'effect':'tree');this.modalRoute='/growth/'+group;this.modal('<button class="close" data-close aria-label="성장 닫기">×</button><div class="eyebrow">도전 밖에서 준비하는 영구 성장 · '+BUILD.version+'</div><h2 id="modalTitle">정원의 성장</h2><div class="growth-heading"><span>선택해 살펴보고, 구매로 확정해요</span><output id="growthBalance"></output></div><nav id="growthTabs" class="growth-tabs" aria-label="성장 분류"></nav><nav class="screen-tabs compact-only growth-stage-tabs" aria-label="성장 조회 단계"><button data-growth-pane="tree">미니 트리</button><button data-growth-pane="effect">선택 효과</button><button data-growth-pane="conditions">조건</button></nav><div class="growth-layout"><div id="growthTree" class="growth-tree" aria-label="성장 미니 트리"></div><section class="growth-detail"><div id="growthDetail"></div><button class="primary" id="growthBuy"></button><p class="growth-note">획득 조개와 구매는 패배·종료·새로고침 후에도 유지돼요. 다음 도전에 적용 · 연습은 재화와 도감 저장 없음</p></section></div>','growth-modal');for(const b of document.querySelectorAll('[data-growth-pane]'))b.onclick=()=>this.setGrowthPane(b.dataset.growthPane);this.renderGrowth()}
